import type {WebSocket} from 'ws';
import {createMessageHandler} from './messageHandler.js';
import type {ChatOrchestrator} from '../../orchestration/chatOrchestrator.js';
import type {ChatSession} from '../../types/session.js';
import type {OutgoingMessage} from '../../types/messages.js';
import type {SessionListOptions, SessionStore} from '../../types/sessionStore.js';
import {setLogger} from '../../shared/logger.js';

const wsErrors: Array<{category: string; message: string; fields?: Record<string, unknown>}> = [];

beforeEach(() => {
  wsErrors.length = 0;
  const ignore = () => undefined;
  setLogger({
    debug: ignore,
    info: ignore,
    warn: ignore,
    error: (category, message, fields) => void wsErrors.push({category, message, fields}),
  });
});

afterEach(() => {
  setLogger();
});

describe('handling list_sessions in the message handler', () => {
  it('lists the session user conversations with ISO dates ahead of a trailing ping, answers empty without listFor, and logs a ws SERVER_ERROR on failure', async () => {
    const recordedCalls: Array<{userId: string | number; options?: SessionListOptions}> = [];
    const listingStore = stubStore(async (userId, options) => {
      recordedCalls.push({userId, options});
      return [
        {
          sessionId: 'conv-1',
          createdAt: new Date('2026-02-01T00:00:00.000Z'),
          updatedAt: new Date('2026-02-01T00:03:00.000Z'),
          entryCount: 2,
        },
      ];
    });
    const cursor = {updatedAt: '2026-02-01T00:05:00.000Z', sessionId: 'cursor-1'};

    const listed = await runBurst(listingStore, [
      {type: 'list_sessions', limit: 5, before: cursor, userId: 'spoofed-user'},
      {type: 'ping', timestamp: 77},
    ]);
    const omittedStore = await runBurst(undefined, [{type: 'list_sessions'}]);
    const omittedMember = await runBurst(stubStore(), [{type: 'list_sessions'}]);
    const rejectedStore = await runBurst(
      stubStore(() => Promise.reject(new Error('store unreachable'))),
      [{type: 'list_sessions'}]
    );

    expect({
      recordedCalls,
      listed,
      omittedStore,
      omittedMember,
      rejectedStore,
      wsErrors,
    }).toEqual({
      recordedCalls: [{userId: 'user-7', options: {limit: 5, before: cursor}}],
      listed: [
        {
          type: 'session_list',
          sessions: [
            {
              sessionId: 'conv-1',
              createdAt: '2026-02-01T00:00:00.000Z',
              updatedAt: '2026-02-01T00:03:00.000Z',
              entryCount: 2,
            },
          ],
        },
        {type: 'pong', timestamp: 77},
